arguments.command:
cat << 'EOF' > get_highest_candidates.py
import pandas as pd
import re
df = pd.read_csv('shg_active.csv')

def get_elements(formula):
    return re.findall(r'[A-Z][a-z]*', formula)

print("Candidate formulas to consider for huge SHG (Te, As, Sb, Hg, Tl, In, Cd):")
for idx, row in df.iterrows():
    els = get_elements(row['formula'])
    if any(el in els for el in ['Te', 'As', 'Sb', 'Hg', 'Tl', 'In', 'Cd']):
        print(f"{row['id']:<5} {row['formula']:<20} {row['sg']}")
EOF
python3 get_highest_candidates.py

